# Kopia progów z CustomUser.rank_for_points — migracja nie może importować modelu.
def _rank_for_points(points):
    if points < 0:
        return "Obserwator"
    if points <= 10:
        return "Nowicjusz"
    if points <= 50:
        return "Pomocnik"
    if points <= 200:
        return "Ekspert"
    return "Mistrz"


def recalculate_ranks(apps, schema_editor):
    """Zastępuje stare nazwy rang (Aktywny Uczeń, Ekspert Społeczności) nowymi."""
    CustomUser = apps.get_model("accounts", "CustomUser")
    for user in CustomUser.objects.only("pk", "reputation_points", "rank_title"):
        rank = _rank_for_points(user.reputation_points)
        if user.rank_title != rank:
            user.rank_title = rank
            user.save(update_fields=["rank_title"])


